// src/users/users.controller.ts
import { Controller, Get, Param, Query, HttpException, HttpStatus } from '@nestjs/common';
import { UsersService } from './users.service';

@Controller('users')
export class UsersController {
  constructor(private readonly usersService: UsersService) {}

  @Get('profile/:username')
  async getProfile(@Param('username') username: string) {
    // Normalize unicode to NFC form for consistent storage lookup
    const normalizedUsername = username.normalize('NFC');

    // Check against blocklist of admin/privileged accounts
    const blockedUsers = ['admin', 'root', 'administrator', 'superuser', 'system'];

    if (blockedUsers.includes(username.toLowerCase())) {
      throw new HttpException('Access denied: cannot view privileged profiles', HttpStatus.FORBIDDEN);
    }

    // After blocklist check, use normalized form for DB lookup
    const profile = await this.usersService.findByUsername(normalizedUsername);
    if (!profile) {
      throw new HttpException('User not found', HttpStatus.NOT_FOUND);
    }
    return profile;
  }

  @Get('search')
  async searchUsers(@Query('q') query: string) {
    // Normalize search input
    const normalizedQuery = query.normalize('NFKC');

    // Basic input validation - reject if contains path traversal
    if (query.includes('..') || query.includes('/')) {
      throw new HttpException('Invalid search query', HttpStatus.BAD_REQUEST);
    }

    // Use normalized form for search (NFKC collapses compatibility chars)
    return this.usersService.searchUsers(normalizedQuery);
  }
}

