import { Entity, Column, PrimaryGeneratedColumn } from 'typeorm';

@Entity()
export class User {
  @PrimaryGeneratedColumn()
  id: number;

  @Column({ unique: true })
  username: string;

  @Column()
  displayName: string;

  @Column({ nullable: true })
  email: string;

  @Column({ default: 'user' })
  role: string;

  @Column({ nullable: true })
  internalNotes: string; // sensitive field, only visible to admin service
}

