import { Controller, Get, Param } from '@nestjs/common';
import { UsersService } from '../users/users.service';

@Controller('internal/admin')
export class AdminController {
  constructor(private readonly usersService: UsersService) {}

  @Get('user-details/:username')
  async getFullUserDetails(@Param('username') username: string) {
    // Internal endpoint - returns full user record including internalNotes
    // Should only be accessible from admin namespace via service mesh
    const user = await this.usersService.findByUsername(username.normalize('NFC'));
    return user;
  }
